def compute(vars):
    share_price = vars["Share Price"]
    outstanding_shares = vars["Outstanding Shares"]

    market_capitalization = share_price * outstanding_shares

    return {
        "value": market_capitalization,
        "trace": {
            "Share Price": share_price,
            "Outstanding Shares": outstanding_shares,
            "output_meta": {
                "currency": "$",
                "scale": None,
                "unit": "$"
            }
        }
    }
